/* ---------------------------- PLACE NAMES ----------------------------
 * The 1511 district and taluka names of Maharashtra, Karnataka, Madhya
 * Pradesh, Gujarat and Rajasthan, written in each language's own script.
 *
 * These are TRANSLITERATIONS, not translations: the name itself is written
 * in another script, never turned into a different word. Only a descriptive
 * suffix on a name is translated — City, Suburban, Rural, Urban, Gramin and
 * the directions — so "Mumbai Suburban" becomes "मुंबई उपनगर", not "Mumbai
 * Upanagar". For each state's own language the spelling is the official one
 * (Marathi for Maharashtra, Kannada for Karnataka, Hindi for MP and
 * Rajasthan, Gujarati for Gujarat); for the other languages it is the form
 * that language's press uses.
 *
 * Two English spellings that stand for the same name — Malia and Maliya,
 * Sayala and Sayla, Badgaon and Vadgam — land on the same word in some
 * scripts. That is correct, not a copy-paste slip.
 *
 * Small tehsils and talukas are the weak spot: where no published spelling
 * could be confirmed the name was written out sound by sound rather than
 * guessed at a better-known place, so a few of them may not match what the
 * local record office prints.
 *
 * Kept in a file of its own so i18n.js stays about the interface. The English
 * name is the key, exactly as LOCATIONS holds it, so tr(district) works
 * everywhere and an unknown name falls back to English instead of breaking.
 *
 * A name whose spelling you know to be wrong can be corrected here alone —
 * nothing else needs to change. */
